(** ** The lap *)

Lemma lap_1RB0LD_1LC1RA_0RB0LC____1RC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
