  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB0LD_1LC1RA_0RB0LC____1RC B0_1RB0LD_1LC1RA_0RB0LC____1RC B1_1RB0LD_1LC1RA_0RB0LC____1RC 4 6 p j' [] []).
