    + reflexivity.
    + reflexivity.
    + exact (gso_1RB0LD_1LC1RA_0RB0LC____1RC p j' E).
    + exact (geo_1RB0LD_1LC1RA_0RB0LC____1RC p j' E).
    + lia.
