  unfold Cc_1RB0LD_1LC1RA_0RB0LC_0LB1RD, cden, Z0_1RB0LD_1LC1RA_0RB0LC_0LB1RD, Z1_1RB0LD_1LC1RA_0RB0LC_0LB1RD; cbn [c_st c_l c_h c_r].
