Lemma geo_1RB0LD_1LC1RA_0RB0LC_0LB1RD : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB0LD_1LC1RA_0RB0LC_0LB1RD) = lift (Cc (Pos.succ p)).
