  - destruct (lapi_1RB0LD_1LC1RA_0RB0LC_0LB1RD p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB0LD_1LC1RA_0RB0LC_0LB1RD B0_1RB0LD_1LC1RA_0RB0LC_0LB1RD B1_1RB0LD_1LC1RA_0RB0LC_0LB1RD 4 6 p j' [] []).
    + exact run_ovf_1RB0LD_1LC1RA_0RB0LC_0LB1RD.
