(** ** Bootstrap *)

Lemma bootq_1RB0LD_1LC1RA_0RB0LC_0LB1RD : stepn tmm_1RB0LD_1LC1RA_0RB0LC_0LB1RD 15 InitES = Some (lift (Cc 2)).
