(** the quasihalt witness: a pinned instruction fired in the prefix *)
Lemma wit_1RB0LD_1LC1RA_0RB0LC_0LB1RD : existsb (fun tg => cfires tmm_1RB0LD_1LC1RA_0RB0LC_0LB1RD c0 15 tg) pins_1RB0LD_1LC1RA_0RB0LC_0LB1RD = true.
