  - exact bootq_1RB0LD_1LC1RA_0RB0LC_0LB1RD.
  - intros p _. apply lap_1RB0LD_1LC1RA_0RB0LC_0LB1RD.
  - intros t Ht p _. apply fire_1RB0LD_1LC1RA_0RB0LC_0LB1RD. exact Ht.
  - exact wit_1RB0LD_1LC1RA_0RB0LC_0LB1RD.
  - apply qcleb_QE_01. reflexivity.
Qed.

Theorem qhtr_1RB0LD_1LC1RA_0RB0LC_0LB1RD : NonHalt tm_1RB0LD_1LC1RA_0RB0LC_0LB1RD /\ QHBoundTr 32779478 tm_1RB0LD_1LC1RA_0RB0LC_0LB1RD /\ QuasiHaltsTr tm_1RB0LD_1LC1RA_0RB0LC_0LB1RD.
Proof. apply (qh_triple_unmirror 32779478 tm_1RB0LD_1LC1RA_0RB0LC_0LB1RD). rewrite mirror_ok_1RB0LD_1LC1RA_0RB0LC_0LB1RD. exact qhtrm_1RB0LD_1LC1RA_0RB0LC_0LB1RD. Qed.

