    apply (lap_of_run tm Cc true true cho_1RB0LD_1LC1RA_0RB0LC_0LC0RD B0_1RB0LD_1LC1RA_0RB0LC_0LC0RD B1_1RB0LD_1LC1RA_0RB0LC_0LC0RD 4 6 p j' [] []).
