  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB0LD_1LC1RA_0RB0LC_0RB0RD
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 1; SWinL 1]).
