    exists (4 * j' + 6). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chp_1RB0LD_1LC1RA_0RB0LC_0RB1RD P0_1RB0LD_1LC1RA_0RB0LC_0RB1RD P1_1RB0LD_1LC1RA_0RB0LC_0RB1RD 4 6
