(** ** Bootstrap *)

Lemma bootq_1RB0LD_1LC1RA_0RB0LC_0RB1RD : stepn tmm_1RB0LD_1LC1RA_0RB0LC_0RB1RD 11 InitES = Some (lift (Cc 1)).
