(** the quasihalt witness: a pinned instruction fired in the prefix *)
Lemma wit_1RB0LD_1LC1RA_0RB0LC_0RB1RD : existsb (fun tg => cfires tmm_1RB0LD_1LC1RA_0RB0LC_0RB1RD c0 11 tg) pins_1RB0LD_1LC1RA_0RB0LC_0RB1RD = true.
