  - exact bootq_1RB0LD_1LC1RA_0RB0LC_0RB1RD.
  - intros p _. apply lap_1RB0LD_1LC1RA_0RB0LC_0RB1RD.
  - intros t Ht p _. apply fire_1RB0LD_1LC1RA_0RB0LC_0RB1RD. exact Ht.
  - exact wit_1RB0LD_1LC1RA_0RB0LC_0RB1RD.
  - apply qcleb_QE_01. reflexivity.
Qed.

Theorem qhtr_1RB0LD_1LC1RA_0RB0LC_0RB1RD : NonHalt tm_1RB0LD_1LC1RA_0RB0LC_0RB1RD /\ QHBoundTr 32779478 tm_1RB0LD_1LC1RA_0RB0LC_0RB1RD /\ QuasiHaltsTr tm_1RB0LD_1LC1RA_0RB0LC_0RB1RD.
Proof. apply (qh_triple_unmirror 32779478 tm_1RB0LD_1LC1RA_0RB0LC_0RB1RD). rewrite mirror_ok_1RB0LD_1LC1RA_0RB0LC_0RB1RD. exact qhtrm_1RB0LD_1LC1RA_0RB0LC_0RB1RD. Qed.

