Lemma lapi_1RB0LD_1LC1RA_0RB0LC_0RC0RD : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
