  - destruct (gz_1RB0LD_1LC1RA_0RB0LC_0RC0RD p q0 E) as (HA & HB).
    exists (0 * 0 + 2). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chz_1RB0LD_1LC1RA_0RB0LC_0RC0RD Z0_1RB0LD_1LC1RA_0RB0LC_0RC0RD Z1_1RB0LD_1LC1RA_0RB0LC_0RC0RD 0 2
               run_z_1RB0LD_1LC1RA_0RB0LC_0RC0RD (Ap_Alph_00_10_1 q0 ++ [S0]) [] 0
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
  - destruct (gp_1RB0LD_1LC1RA_0RB0LC_0RC0RD p j' q0 E) as (HA & HB).
    exists (4 * j' + 6). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chp_1RB0LD_1LC1RA_0RB0LC_0RC0RD P0_1RB0LD_1LC1RA_0RB0LC_0RC0RD P1_1RB0LD_1LC1RA_0RB0LC_0RC0RD 4 6
