Lemma geo_1RB0LD_1LC1RA_0RB0LC_0RC0RD : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB0LD_1LC1RA_0RB0LC_0RC0RD) = lift (Cc (Pos.succ p)).
