  { unfold Cc_1RB0LD_1LC1RA_0RB0LC_0RC0RD. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lbl_1RB0LD_1LC1RA_0RB0LC_0RC0RD. reflexivity.
