  - destruct (lapi_1RB0LD_1LC1RA_0RB0LC_0RC0RD p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB0LD_1LC1RA_0RB0LC_0RC0RD B0_1RB0LD_1LC1RA_0RB0LC_0RC0RD B1_1RB0LD_1LC1RA_0RB0LC_0RC0RD 4 6 p j' [] []).
    + exact run_ovf_1RB0LD_1LC1RA_0RB0LC_0RC0RD.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB0LD_1LC1RA_0RB0LC_0RC0RD p j' E).
    + exact (geo_1RB0LD_1LC1RA_0RB0LC_0RC0RD p j' E).
