(** ** Bootstrap *)

Lemma bootq_1RB0LD_1LC1RA_0RB0LC_0RC0RD : stepn tmm_1RB0LD_1LC1RA_0RB0LC_0RC0RD 12 InitES = Some (lift (Cc 1)).
