  apply (lap_qh_stage tmm_1RB0LD_1LC1RA_0RB0LC_0RC0RD pins_1RB0LD_1LC1RA_0RB0LC_0RC0RD Cc 1 12 32779478).
  - exact bootq_1RB0LD_1LC1RA_0RB0LC_0RC0RD.
  - intros p _. apply lap_1RB0LD_1LC1RA_0RB0LC_0RC0RD.
  - intros t Ht p _. apply fire_1RB0LD_1LC1RA_0RB0LC_0RC0RD. exact Ht.
  - exact wit_1RB0LD_1LC1RA_0RB0LC_0RC0RD.
  - apply qcleb_QE_01. reflexivity.
Qed.

Theorem qhtr_1RB0LD_1LC1RA_0RB0LC_0RC0RD : NonHalt tm_1RB0LD_1LC1RA_0RB0LC_0RC0RD /\ QHBoundTr 32779478 tm_1RB0LD_1LC1RA_0RB0LC_0RC0RD /\ QuasiHaltsTr tm_1RB0LD_1LC1RA_0RB0LC_0RC0RD.
