  - exact bootq_1RB0LD_1LC1RA_0RB0LC_0RC1LD.
  - intros p _. apply lap_1RB0LD_1LC1RA_0RB0LC_0RC1LD.
  - intros t Ht p _. apply fire_1RB0LD_1LC1RA_0RB0LC_0RC1LD. exact Ht.
  - exact wit_1RB0LD_1LC1RA_0RB0LC_0RC1LD.
  - apply qcleb_QE_01. reflexivity.
Qed.

