Lemma wit_1RB0LD_1LC1RA_0RB0LC_1LC0LD : existsb (fun tg => cfires tmm_1RB0LD_1LC1RA_0RB0LC_1LC0LD c0 10 tg) pins_1RB0LD_1LC1RA_0RB0LC_1LC0LD = true.
Proof. vm_compute. reflexivity. Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB0LD_1LC1RA_0RB0LC_1LC0LD : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB0LD_1LC1RA_0RB0LC_1LC0LD = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB0LD_1LC1RA_0RB0LC_1LC0LD p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB0LD_1LC1RA_0RB0LC_1LC0LD p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB0LD_1LC1RA_0RB0LC_1LC0LD : forall t, ~ In t pins_1RB0LD_1LC1RA_0RB0LC_1LC0LD ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_1RB0LD_1LC1RA_0RB0LC_1LC0LD.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_via_ovf tm Cc Hi (StA, S0)), fireo_1RB0LD_1LC1RA_0RB0LC_1LC0LD
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 1]).
    vm_compute; reflexivity.
  - (* A1: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB0LD_1LC1RA_0RB0LC_1LC0LD
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 1; SWinL 1]).
    vm_compute; reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_1RB0LD_1LC1RA_0RB0LC_1LC0LD
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB0LD_1LC1RA_0RB0LC_1LC0LD
      with (l := []).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB0LD_1LC1RA_0RB0LC_1LC0LD
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 1; SWinL 2]).
    vm_compute; reflexivity.
  - (* D0: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* D1: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
Qed.

Theorem qhtrm_1RB0LD_1LC1RA_0RB0LC_1LC0LD : NonHalt tmm_1RB0LD_1LC1RA_0RB0LC_1LC0LD /\ QHBoundTr 32779478 tmm_1RB0LD_1LC1RA_0RB0LC_1LC0LD /\ QuasiHaltsTr tmm_1RB0LD_1LC1RA_0RB0LC_1LC0LD.
Proof.
  apply (lap_qh_stage tmm_1RB0LD_1LC1RA_0RB0LC_1LC0LD pins_1RB0LD_1LC1RA_0RB0LC_1LC0LD Cc 1 10 32779478).
  - exact bootq_1RB0LD_1LC1RA_0RB0LC_1LC0LD.
  - intros p _. apply lap_1RB0LD_1LC1RA_0RB0LC_1LC0LD.
  - intros t Ht p _. apply fire_1RB0LD_1LC1RA_0RB0LC_1LC0LD. exact Ht.
  - exact wit_1RB0LD_1LC1RA_0RB0LC_1LC0LD.
  - apply qcleb_QE_01. reflexivity.
Qed.

Theorem qhtr_1RB0LD_1LC1RA_0RB0LC_1LC0LD : NonHalt tm_1RB0LD_1LC1RA_0RB0LC_1LC0LD /\ QHBoundTr 32779478 tm_1RB0LD_1LC1RA_0RB0LC_1LC0LD /\ QuasiHaltsTr tm_1RB0LD_1LC1RA_0RB0LC_1LC0LD.
